contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // The test takes an address `from`, a target contract address `caddress`,
    // dynamic arrays `_tos` and `v`. It asserts that for any non-empty _tos,
    // c.transfer(...) returns true (i.e., does not revert and returns true).
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0);
        // Call transfer and capture whether it reverted and the returned value.
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }
        // General rule: when _tos.length > 0, transfer must NOT revert and must return true.
        assert(!reverted && ret == true);
    }
    receive() external payable {}
}

